create table if not exists public.timeline_daw_private_midi_clips(id text primary key,owner_id uuid not null references auth.users(id) on delete cascade,session_id text not null,name text not null,revision bigint not null default 0 check(revision>=0),ppq integer not null check(ppq between 24 and 9600),length_ticks bigint not null check(length_ticks>0),start_tick bigint not null default 0 check(start_tick>=0),instrument jsonb not null,notes jsonb not null default '[]'::jsonb,controllers jsonb not null default '[]'::jsonb,checksum text not null check(checksum~'^sha256:[a-f0-9]{64}$'),provenance text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(owner_id,session_id,id));
create table if not exists public.timeline_daw_private_midi_history(id text primary key,owner_id uuid not null references auth.users(id) on delete cascade,session_id text not null,clip_id text not null,before_state jsonb,after_state jsonb,operation text not null check(operation in('create','save','delete','undo','redo','import')),state text not null default 'applied' check(state in('applied','undone')),created_at timestamptz not null default now());
alter table public.timeline_daw_private_midi_clips enable row level security;alter table public.timeline_daw_private_midi_history enable row level security;
create policy timeline_daw_private_midi_clips_owner on public.timeline_daw_private_midi_clips for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy timeline_daw_private_midi_history_owner on public.timeline_daw_private_midi_history for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create index if not exists timeline_daw_private_midi_clips_session on public.timeline_daw_private_midi_clips(owner_id,session_id,start_tick);
create index if not exists timeline_daw_private_midi_history_clip on public.timeline_daw_private_midi_history(owner_id,session_id,clip_id,created_at desc);
